const b = $input.first().json.body ?? $input.first().json;
const topic = String(b.topic || 'agrovoltaica en Extremadura');
const mk = String($env.MISTRAL_API_KEY || '').trim();
if (!mk) {
  return [{
    json: {
      success: false,
      error: 'MISTRAL_API_KEY no configurada',
      topic,
      markdown_fallback: '# Contenido educativo\n\nConfigura MISTRAL_API_KEY en n8n para generación dinámica.',
    },
  }];
}
const r = await fetch('https://api.mistral.ai/v1/chat/completions', {
  method: 'POST',
  headers: { Authorization: `Bearer ${mk}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    model: 'mistral-small-latest',
    messages: [
      {
        role: 'system',
        content:
          'Eres experta agrovoltaica UE. Responde en Markdown claro, sin diagnóstico médico, sin cifras inventadas.',
      },
      {
        role: 'user',
        content: `Explica de forma técnica y pedagógica: ${topic}. Incluye secciones y bullet points.`,
      },
    ],
  }),
});
const t = await r.text();
let out;
try { out = JSON.parse(t); } catch { out = { raw: t }; }
const text = out.choices?.[0]?.message?.content || '';
return [{ json: { success: r.ok, topic, mistral: out, markdown: text } }];
